begin;
set local search_path=extensions,public,pg_catalog;
select no_plan();
-- Disposable transaction-only identities; no mail, provider authorization or application fixtures.
insert into auth.users(id,email,encrypted_password,email_confirmed_at,confirmation_token,recovery_token,raw_app_meta_data,raw_user_meta_data) values
('ad640000-0000-4000-8000-000000000001','android-binding-new@example.test','test-hash',null,'signup-token','', '{"role":"customer"}','{}'),
('ad640000-0000-4000-8000-000000000002','android-binding-ready@example.test','test-hash',now(),'','recovery-token','{"role":"customer"}','{}');
select set_config('android.request','{"request_id":"ad640000-0000-4000-8000-000000000011","user_id":"ad640000-0000-4000-8000-000000000001","email":"android-binding-new@example.test","client":"android","native_state":"ad640000-0000-4000-8000-000000000012","native_challenge":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","pending_handle":"ad640000-0000-4000-8000-000000000013"}',true);
select ok(not has_function_privilege('anon','public.customer_native_email_api(text,jsonb)','EXECUTE'),'anonymous cannot mint signup bindings');
select ok(not has_function_privilege('authenticated','public.customer_native_email_api(text,jsonb)','EXECUTE'),'signed-in clients cannot mint signup bindings');
select ok(has_function_privilege('service_role','public.customer_native_email_api(text,jsonb)','EXECUTE'),'only trusted gateway may call signup protocol');
select ok(not has_table_privilege('service_role','private.customer_native_email_requests','SELECT'),'even service callers use bounded protocol');
select throws_ok($$select public.customer_native_email_api('start',current_setting('android.request')::jsonb||'{"client":"ios"}')$$,'P0001','INVALID_REQUEST','signup protocol cannot reinterpret an iOS request');
select throws_ok($$select public.customer_native_email_api('start',current_setting('android.request')::jsonb||'{"email":"another@example.test"}')$$,'P0001','INVALID_REQUEST','signup identity comes from Auth');
select throws_ok($$select public.customer_native_email_api('start',current_setting('android.request')::jsonb||'{"user_id":"ad640000-0000-4000-8000-000000000002"}')$$,'P0001','INVALID_REQUEST','already confirmed identity cannot be onboarded');
select lives_ok($$select public.customer_native_email_api('start',current_setting('android.request')::jsonb)$$,'new unconfirmed customer gets device-bound request');
select ok((select pending_hash<> 'ad640000-0000-4000-8000-000000000013' from private.customer_native_email_requests where id='ad640000-0000-4000-8000-000000000011'),'pending handle is hashed at rest');
select lives_ok($$select public.customer_native_email_api('ready',current_setting('android.request')::jsonb)$$,'sent signup captures current provider token privately');
select throws_ok($$select public.customer_native_email_api('status',current_setting('android.request')::jsonb||'{"pending_handle":"ad640000-0000-4000-8000-000000000099"}')$$,'P0001','INVALID_CODE','status requires original pending capability');
select throws_ok($$select public.customer_native_email_api('status',current_setting('android.request')::jsonb||'{"native_challenge":"BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB"}')$$,'P0001','INVALID_CODE','status cannot switch device challenge');
select is(public.customer_native_email_api('status',current_setting('android.request')::jsonb)->>'status','ready','pending owner may poll readiness');
select throws_ok($$select public.customer_native_email_api('delivery',current_setting('android.request')::jsonb||'{"token_hash":"wrong"}')$$,'P0001','INVALID_CODE','callback requires exact provider credential');
select set_config('android.delivery',public.customer_native_email_api('delivery',current_setting('android.request')::jsonb||'{"token_hash":"signup-token"}')->>'deliveryToken',true);
select ok(length(current_setting('android.delivery'))=36,'callback returns only opaque random delivery handle');
select ok((select delivery_hash<>current_setting('android.delivery') from private.customer_native_email_requests where id='ad640000-0000-4000-8000-000000000011'),'delivery handle is hashed at rest');
select throws_ok($$select public.customer_native_email_api('reserve',current_setting('android.request')::jsonb||jsonb_build_object('delivery_token',current_setting('android.delivery'),'native_challenge',repeat('B',43)))$$,'P0001','INVALID_CODE','intercepted delivery cannot bypass original device verifier');
select throws_ok($$select public.customer_native_email_api('reserve',current_setting('android.request')::jsonb||'{"client":"ios"}')$$,'P0001','INVALID_CODE','cross-client redemption is denied');
select set_config('android.operation',public.customer_native_email_api('reserve',current_setting('android.request')::jsonb||jsonb_build_object('delivery_token',current_setting('android.delivery')))->>'operation',true);
select throws_ok($$select public.customer_native_email_api('reserve',current_setting('android.request')::jsonb)$$,'P0001','INVALID_CODE','second concurrent reservation cannot consume credential');
select throws_ok($$select public.customer_native_email_api('resend',current_setting('android.request')::jsonb)$$,'P0001','INVALID_CODE','resend cannot invalidate verification in progress');
select throws_ok($$select public.customer_native_email_api('invalid-code',current_setting('android.request')::jsonb||'{"operation":"ad640000-0000-4000-8000-000000000099"}')$$,'P0001','INVALID_CODE','only same verification operation may release lease');
select lives_ok($$select public.customer_native_email_api('invalid-code',current_setting('android.request')::jsonb||jsonb_build_object('operation',current_setting('android.operation')))$$,'definitively invalid code permits another code attempt');
select throws_ok($$select public.customer_native_email_api('reserve',current_setting('android.request')::jsonb||jsonb_build_object('delivery_token',current_setting('android.delivery')))$$,'P0001','INVALID_CODE','consumed delivery handle cannot replay');
select set_config('android.operation',public.customer_native_email_api('reserve',current_setting('android.request')::jsonb)->>'operation',true);
select lives_ok($$select public.customer_native_email_api('uncertain',current_setting('android.request')::jsonb||jsonb_build_object('operation',current_setting('android.operation')))$$,'uncertain provider result closes the operation');
select throws_ok($$select public.customer_native_email_api('reserve',current_setting('android.request')::jsonb)$$,'P0001','INVALID_CODE','uncertain verification is not automatically repeated');
select set_config('android.expiry',(select expires_at::text from private.customer_native_email_requests where id='ad640000-0000-4000-8000-000000000011'),true);
select lives_ok($$select public.customer_native_email_api('resend',current_setting('android.request')::jsonb)$$,'owner may explicitly request fresh signup delivery');
select is((select expires_at::text from private.customer_native_email_requests where id='ad640000-0000-4000-8000-000000000011'),current_setting('android.expiry'),'resend never extends original expiry');
update auth.users set confirmation_token='new-signup-token' where id='ad640000-0000-4000-8000-000000000001';
select public.customer_native_email_api('ready',current_setting('android.request')::jsonb);
select throws_ok($$select public.customer_native_email_api('delivery',current_setting('android.request')::jsonb||'{"token_hash":"signup-token"}')$$,'P0001','INVALID_CODE','resend invalidates old provider token');
select set_config('android.operation',public.customer_native_email_api('reserve',current_setting('android.request')::jsonb)->>'operation',true);
update auth.users set email_confirmed_at=now(),confirmation_token='' where id='ad640000-0000-4000-8000-000000000001';
insert into auth.sessions(id,user_id,created_at,updated_at) values ('ad640000-0000-4000-8000-000000000021','ad640000-0000-4000-8000-000000000001',now(),now());
select throws_ok($$select public.customer_native_email_api('verified',current_setting('android.request')::jsonb||jsonb_build_object('operation',current_setting('android.operation'),'session_id','ad640000-0000-4000-8000-000000000021'))$$,'P0001','INVALID_CODE','ordinary session is insufficient to finish signup');
insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),'ad640000-0000-4000-8000-000000000021','otp',now(),now());
select lives_ok($$select public.customer_native_email_api('verified',current_setting('android.request')::jsonb||jsonb_build_object('operation',current_setting('android.operation'),'session_id','ad640000-0000-4000-8000-000000000021'))$$,'fresh matching OTP session completes signup once');
select is(public.customer_native_email_api('status',current_setting('android.request')::jsonb)->>'status','verified','pending owner sees completed state');
select ok((select token_hash is null and delivery_hash is null and operation is null from private.customer_native_email_requests where id='ad640000-0000-4000-8000-000000000011'),'verified request retains no usable delivery credential');
select throws_ok($$select public.customer_native_email_api('reserve',current_setting('android.request')::jsonb)$$,'P0001','INVALID_CODE','verified signup cannot replay');
update private.customer_native_email_requests set expires_at=now()-interval '1 second' where id='ad640000-0000-4000-8000-000000000011';
select throws_ok($$select public.customer_native_email_api('status',current_setting('android.request')::jsonb)$$,'P0001','INVALID_CODE','expired pending handles stop working');

select set_config('android.password','{"request_id":"ad640000-0000-4000-8000-000000000031","email":"android-binding-ready@example.test","client":"android","purpose":"recovery","native_state":"ad640000-0000-4000-8000-000000000032","native_challenge":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"}',true);
select lives_ok($$select public.customer_password_api('request-start',current_setting('android.password')::jsonb)$$,'password recovery accepts explicit Android binding');
select public.customer_password_api('request-ready',current_setting('android.password')::jsonb);
select throws_ok($$select public.customer_password_api('request-load',current_setting('android.password')::jsonb||'{"client":"web"}')$$,'P0001','INVALID_CODE','web cannot redeem Android recovery');
select throws_ok($$select public.customer_password_api('request-load',current_setting('android.password')::jsonb||'{"client":"ios"}')$$,'P0001','INVALID_CODE','iOS cannot redeem Android recovery');
select throws_ok($$select public.customer_password_api('request-load',current_setting('android.password')::jsonb||'{"native_challenge":"BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB"}')$$,'P0001','INVALID_CODE','password recovery requires original verifier hash');
select throws_ok($$select public.customer_password_api('request-delivery',current_setting('android.password')::jsonb||'{"client":"ios","token_hash":"recovery-token"}')$$,'P0001','INVALID_CODE','delivery cannot cross native platforms');
select lives_ok($$select public.customer_password_api('request-load',current_setting('android.password')::jsonb)$$,'matching Android recovery binding loads privately');
select set_config('android.delivery',public.customer_password_api('request-delivery',current_setting('android.password')::jsonb||'{"token_hash":"recovery-token"}')->>'deliveryToken',true);
select lives_ok($$select public.customer_password_api('request-load',current_setting('android.password')::jsonb||jsonb_build_object('delivery_token',current_setting('android.delivery')))$$,'opaque recovery delivery is device bound');
select throws_ok($$select public.customer_password_api('request-load',current_setting('android.password')::jsonb||'{"delivery_token":"ad640000-0000-4000-8000-000000000099"}')$$,'P0001','INVALID_CODE','wrong recovery delivery is rejected');
select * from finish();
rollback;
